def edited(text):
    clean = text.replace("?", "!")
    return clean, clean.find("!")

def positional(name, score):
    return "{0}: {1}".format(name, score)

def named(name, score):
    return "{who}: {points}".format(who=name, points=score)

print(edited("Ready?"))
